#include "renderer/Renderer.hpp"
#include "renderer/PrimitiveMeshes.hpp"
#include "renderer/Lighting.hpp"
#include <glm/gtc/type_ptr.hpp>
#include <GLFW/glfw3.h>
#include <iostream>
namespace scene_editor {
bool Renderer::initialize(){cube=makeCube();sphere=makeSphere();plane=makePlane();return shader.load(std::string(SCENE_EDITOR_ASSET_DIR)+"/shaders/phong.vert",std::string(SCENE_EDITOR_ASSET_DIR)+"/shaders/phong.frag");}
void Renderer::shutdown(){sceneRenderer.shutdown();cube.reset();sphere.reset();plane.reset();shader.reset();if(depthBuffer_)glDeleteRenderbuffers(1,&depthBuffer_);if(colorTexture_)glDeleteTextures(1,&colorTexture_);if(framebuffer_)glDeleteFramebuffers(1,&framebuffer_);depthBuffer_=colorTexture_=framebuffer_=0;width=height=0;}
void Renderer::resize(int w,int h){w=w>0?w:1;h=h>0?h:1;if(w==width&&h==height&&framebuffer_)return;width=w;height=h;if(!framebuffer_)glGenFramebuffers(1,&framebuffer_);if(!colorTexture_)glGenTextures(1,&colorTexture_);if(!depthBuffer_)glGenRenderbuffers(1,&depthBuffer_);glBindFramebuffer(GL_FRAMEBUFFER,framebuffer_);glBindTexture(GL_TEXTURE_2D,colorTexture_);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,width,height,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,colorTexture_,0);glBindRenderbuffer(GL_RENDERBUFFER,depthBuffer_);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH24_STENCIL8,width,height);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_STENCIL_ATTACHMENT,GL_RENDERBUFFER,depthBuffer_);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)std::cerr<<"Viewport framebuffer creation failed\n";glBindFramebuffer(GL_FRAMEBUFFER,0);}
void Renderer::draw(const Scene&s,const Camera&c){const double begin=glfwGetTime();glBindFramebuffer(GL_FRAMEBUFFER,framebuffer_);glViewport(0,0,width,height);glEnable(GL_DEPTH_TEST);glClearColor(.06F,.07F,.1F,1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);shader.use();auto view=c.view(),projection=c.projection(float(width)/float(height));glUniformMatrix4fv(shader.uniform("view"),1,GL_FALSE,glm::value_ptr(view));glUniformMatrix4fv(shader.uniform("projection"),1,GL_FALSE,glm::value_ptr(projection));glm::vec3 vp=c.position();glUniform3fv(shader.uniform("viewPos"),1,glm::value_ptr(vp));uploadLights(s.lights,shader);sceneRenderer.draw(s,shader,cube,sphere,plane);glBindFramebuffer(GL_FRAMEBUFFER,0);frameSeconds_=glfwGetTime()-begin;}
}
